import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    i = 1
    values = []
    alive = []
    out = []
    for _ in range(n):
        if data[i] == "1":
            values.append(int(data[i + 1]))
            alive.append(True)
            i += 2
        else:
            i += 1
            best = -1
            for j in range(len(values)):
                if alive[j] and (best == -1 or values[j] < values[best]):
                    best = j
            if best == -1:
                out.append("-1")
            else:
                alive[best] = False
                out.append(str(values[best]))
    print("\n".join(out))


main()
